from math import comb
from typing import List, Tuple

def subseq_count_mod(n: int, s: List[str]) -> List[int]:
    mod = 998244353
    dp = {("", 0)}

    for combi in range(1, 1 << n):
        char_count = {}
        for char in s:
            char_count[char] = char_count.get(char, 0) + 1
            key = ''.join(sorted(char_count.items(), key=lambda x: x[0]))
            dp.add(key)

    dp_frequency = {}
    for key in dp:
        lower = key.partition("(")[0]
        dp_frequency[key] = dp_frequency.get(lower, 0) + 1

    for subseq in dp:
        occurence = 1
        for k in subseq:
            occurence = occurence * comb(dp_frequency[k], combi) % mod
        yield occurence

def calculate_xor_mod(sequence: List[str], mod: int) -> Tuple[int, int]: 
    total_xor = 0
    total_products = 1
    for subseq in bin(len(sequence) - 1)[2:]:       # Check all subsequences (subseq = len(sequence) - 1)
        subseq = int(subseq[::-1])
        subseq_count = subseq_count_mod(len(sequence), sequence)
        subseq_mod = sum([n for n in subseq]) % mod        # sum is multiplication k if we think that every one number is a multiplicator
        total_xor = (total_xor + total_products * subseq_mod) % mod
        total_products = (total_products * subseq_count) % mod
    return total_xor % mod

