    tree = [None] * (n+1)
    for level in range(1, n+1):
        for position in range(1, cnt[level]+1):
            if is_power_of_two(position):
                tree[level] = TreeNode(level, position)
                tree[level].left = cnt[level] + 1
                tree[level].right = cnt[level] + 2
                cnt[level + 1] += 2
            else:
                tree[level] = TreeNode(level, position)
                tree[level].right = cnt[level] + 1
                cnt[level + 1] += 1
    return tree

def is_power_of_two(num):
