def union_of_children(node):
    parent = node.get_parent()
    if parent:
        left_child = node.left
        right_child = node.right
        if left_child != -1:
            parent.add_child(left_child)
            parent.children[-1] -= 1
        if right_child != -1:
            parent.add_child(right_child)
            parent.children[-1] -= 1
    return sum(parent.children)

