import math

def dp(n, m):
    MOD = 1000000007
    dp = [[0] * (1 << m) for _ in range(n + 1)]

    for i in range(1 << m):
        dp[1][i] = 1

    for c in range(2, n + 1):
        for state in range(1 << m):
            curr_state = []
            for bit in range(m):
                if (state & (1 << bit)) > 0:
                    curr_state.append(bit + 1)
            dp[c][state] = dp[c-1][state]
            for bit in curr_state:
                k = len(curr_state)
                for j in range(k):
                    l = k - 1 - j
                    neighbor = []
                    for b in range(m):
                        if (state & (1 << b)) > 0 and b not in curr_state:
                            neighbor.append(b + 1)
                    dp[c][state] += dp[c-1][state - (1 << bit)] * sum(dp[c-1][state2 - (1 << b)] for b in neighbor)
                    dp[c][state] %= MOD

    return dp[n][(1 << m) - 1]

