            for c_digit in str(c):
                if a_digit + b_digit + c_digit in ['000', '111']:
                    partial = a_digit + b_digit
                    total = a_digit + b_digit + c_digit
                    if len(partial) + len(total) < min_len:
                        min_len = len(partial) + len(total)
                        res = partial + total
