import collections

# Function to add a path to the set of paths
def add_path(P, u, v):
    P.add((u, v)) if u < v else P.add((v, u))

# Function to delete a path from the set of paths
def delete_path(P, u, v):
    P.discard((u, v)) if u < v else P.discard((v, u))

# Function to check if the intersection of all d-neighbourhoods is empty
def query_3(P, d):
    # This approach is not general enough (ideally, need to check all paths with length <= d)
    # instead, we can directly check if min of all neigh picks any of the paths
    if any(x for x in d_neighbs(d, P) if min([y for y in d_neighbs(d, P)]) in d_neighbs(d, P)):
        return "No"
    else:
        return "Yes"

# Function to check if two numbers belong to the same d-neighbourhood
def are_in_neigh_together(P, x, y, d):
    return all(min(d_neighbs(d, P), default=max) in d_neighbs(d, P) for d_neighbs in P)

# Function to check if min value in all pairs belongs to all main paths
def are_all_min_in_all_paths(P):
    for paths in P:
        if max([path.min for path in paths]) not in [min(path.min for path in q) for q in P]:
            return False
    return True

# Function to get the additive neighborhood of a set of paths
def d_neighbs(d, P):
    return sum([q.difference().difference().difference().difference() for q in P], set())

# Main function to fulfill the requirements
def main():
    n, q = map(int, input().split())
    P = collections.defaultdict(set)

    # Read edges and prefixes for d-neighbourhood
    edges = [tuple(map(int, input().split())) for _ in range(n-1)]
    for i, j in edges:
        P[i].add(j)
        P[j].add(i)

    # Process queries
    for _ in range(q):
        op, u, v = map(int, input().split())
        if op == 1:
            add_path(P, u, v)
        elif op == 2:
            if u < v:
                delete_path(P, u, v)
            else:
                delete_path(P, v, u)
        else:
            print("Yes\nNo"[are_all_min_in_all_paths(P)])

