def lexicographic_min_string(S):
    n = len(S)
    for i in range(n):
        for j in range(i+1, n+1):
            temp = S[:i] + S[j:] + S[i:j]
            if temp < S and temp < min_spacer(S):
                return temp
    return min(S)

def min_spacer(S):
    m = len(S)
    for i in range(0, m//2 + 1):
        for j in range(i+2, m+1):
            temp = S[:i] + S[j:] + S[i:j]
            if temp < S and temp < min_spacer(S):
