import sys

def find_repeating_block(s):
    n = len(s)
    if n == 1:
        return s
    for i in range(1, n // 2):
        if s[:i] * 2 == s:
            return s[:i]
    return s

def merge(s):
    while True:
        tar = find_repeating_block(s)
        if len(tar) == 0:
            break
        i = s.find(tar)
        # Handle the remaining suffix (importantly, this is always non-empty)
        suffix = s[i+len(tar):]
        s = s[:i] + merge(suffix)
    return s

