def tree_diameter(n, P):
    # This function computes the longest path in a tree.
    # It uses the reverse tree to find the longest path.
    stack = [(0, -1)]
    last = {0: 0}
    path_lengths = {key: -1 for key in range(1, n+1)}
    diameter = 0
    while stack:
        parent, i = stack[-1]
        for child in P[i]:
            if child == 0 and last[i] != -1:
                break
            if child > 0:
                if path_lengths[i] > path_lengths[child]:
                    break
            if child > 0:
                stack.append((child, i))
                break
        if not (child > 0):
            stack.pop()
            l = 0 if last[i] < 0 else last[i] + 1
            path_lengths[last[i]] = (path_lengths[i] + 1 if last[i] > 0 else path_lengths[i])
            last[i] = last[child]
            if child > 0:
                last[i] = path_lengths.index(l)
        if not len(path_lengths) - stack[-1][1] == diameter:
            diameter = len(path_lengths) - stack[-1][1]
    return diameter

