from functools import lru_cache

mod = 1000000007

def count_ways(n, m):
    @lru_cache(maxsize=None)
    def dp(row, col):
        if row == 1 and col == 0:
            return 1
        if col < 2:
            return 2
        if row == n and col <= m:
            return 1
        if row == n and col > m:
            return 0
        return (dp(row - 1, col - 1) + dp(row - 2, col - 2) + dp(row - 1, col - 2)) % mod

    total_ways = 0
    for col in range(1, m + 1):
        ways_now = dp(n - 1, col - 1)
        if col % 2 == 0:
            total_ways += ways_now
        else:
            total_ways += 2 * ways_now
        total_ways %= mod

    return total_ways

