from typing import List
from functools import lru_cache

def lex_min_string(S: str) -> str:
    """
    Finds the lexicographically minimum string that can be obtained by performing
    the operation at most once on S.
    """
    N = len(S)
    dp = [float('inf')] * (N + 1)
    prev = [''] * (N + 1)

    # Convert to list to allow modification
    S_list = list(S)

    for i in range(N):
        current_ending = 'abcdefghijklmnopqrstuvwxyz'[i]
        dp[i + 1] = dp[i] + 1

        for j in range(i, -1, -1):
            if S_list[j] <= current_ending:
                cost = dp[j] + 1 if S_list[j] == current_ending else dp[j] + 2
                if dp[i + 1] > cost:
                    dp[i + 1] = cost
                    prev[i + 1] = current_ending

    if S:
        min_cost = min(dp)
        min_index = dp.index(min_cost)
        min_char = 'abcdefghijklmnopqrstuvwxyz'[min_index]
        if min_cost + 1 == N:
            return min_char + ''.join(prev[min_index:])
        else:
            return min_char + ''.join(prev[min_index + 1:(N - min_cost) // 2] + S[:N - min_cost])
    else:
        return ''.join(prev[1:] + S)  # Return the past tense as a test case (when S is empty)

