            self.colors[v] = color

    def perform_query(self, query_type, v, *args):
        if query_type == 1:
            return 0 if self.get_colors(v) == 0 else 1
        if query_type == 2:
            self.set_color(v, args[1])
        if query_type == 3:
            self.colors[v] = args[1]

class QueryReader:
    def __init__(self, file_path):
        self.file = open(file_path, 'r')
        self.query_count = int(self.file.readline())
        self.queries = []
        self.current_query = 0
        self.read_queries()

    def read_queries(self):
        self.file.seek(1, 1)
        for _ in range(self.query_count):
            self.queries.append(self.parse_query(self.file.readline()))

    def parse_query(self, line):
        elements = line.strip().split()
        return int(elements[0]), int(elements[1]), int(elements[2:]) if len(elements) > 2 else []

def main(query_reader):
    tree = Tree()
    for _ in range(query_reader.query_count):
        v = tree.parse_query(next(query_reader))[1]
        print(tree.perform_query(*next(query_reader)))
    query_reader.file.close()

inputs_file = "input.txt"
output_file = "output.txt"
query_reader = QueryReader(inputs_file)
with open(output_file, "w") as writer:
    main(query_reader)
