import re

def find_solution(expression):
    # Finding the positions of '+' and '=' in the expression
    nums = [match[1] for match in re.finditer(r'(\d+)\+(\d+)', expression)]

    # Making a tuple of numbers without the '+' and '='
    numbers = tuple(re.sub(r'[\+\=]', '', num) for num in nums)

    # Iterating over all combinations of removing digits from numbers
    for n1 in numbers:
        for n2 in numbers:
            for n3 in numbers:
                # Constructing the new expression by adding '/' for '=' in the original expression
                new_expression = expression.replace('+', '/')[:3]
                new_expression += f"{n1}{n2}{n3}{new_expression.replace('/', '')}"

                # If we reach a number to the right after '/' and know which numbers were subtracted,
                # Then given expression becomes a+B=C
                if myfunc(new_expression) == 1:
                    return new_expression

def myfunc(expression):
    # Parsing all the indices of '+' and '=' in the expression
    numbers = [match[1] for match in re.finditer(r'(\d+)\+(\d+)', expression)]
    for i in range(0, len(expression) - 3, 3):
        # Checking consecutive sequence of '+' and '=' substring in expression 
        if expression[i+1:i+3] == "+" and expression[i+4:i+6] == "=":
            # Finding adjacentNumber of expression on left side
            for i2 in range(len(numbers) + 1):
                if int(numbers[i2]) < int(expression[i+1:i+3]):
                    continue
                # Finding adjacentNumber of expression on right side
                for i3 in range(len(numbers) - 1, -1, -1):
                    if int(expression[i+4:i+6]) < int(numbers[i3]):
                        continue
                    # Building new expression from original and comparing if it is also valid 
                    new_expression = expression[:i] + str(int(i2+1)) + expression[i+3:]
                    if myfunc(new_expression) == 1:
                        return 1
    return 0

expression = input()
result = find_solution(expression)
