MOD = 10**9 + 7

def count_winning_arrays(N, B):
    dp = [set([])]
    for b in reversed(B):
        next_dp = set()
        for current_set in dp:
            for x in current_set:
                if (x - b) >= 0:
                    y = (x - b) // 2
                    if y < b:
                        next_dp.add({y})
                    else:
                        next_dp.add({x, y})
            next_dp.add({b})
        dp.append(dp[-1] | next_dp)
    return len(dp[-1]) % MOD

