from collections import defaultdict

def build_tree():
    T = int(input().strip())
    for _ in range(T):
        N = int(input().strip())
        tree = defaultdict(list)
        for _ in range(N-1):
            P = int(input().strip())
            tree[P].append(N)
        return tree

def diameter(tree):
    def dfs(node, prev, depth=1, max_depth=0):
        nonlocal count
        biggest = max_depth
        for child in tree[node]:
            if child != prev:
                biggest = max(biggest, dfs(child, node, depth+1, max(max_depth, depth)))
        if biggest != max_depth:
            count += 1
        return biggest

    count = 0
    dfs(1, -1)
    print(count)
    return count

tree = build_tree()
count = 0
for i in range(2, len(tree)):
    diameter(tree)
